fn hqq_execution_json_value(exec: &HqqExecutionDescriptor) -> serde_json::Value {
    match exec {
        HqqExecutionDescriptor::Gqa(desc) => {
            let mut tensors = vec![hqq_tensor_exec_json(&desc.o_proj, "o_proj")];
            let projection_mode = if let Some(fused_qkv) = &desc.fused_qkv {
                tensors.insert(0, hqq_tensor_exec_json(fused_qkv, "fused_qkv"));
                "fused_qkv"
            } else {
                tensors.insert(0, hqq_tensor_exec_json(&desc.v_proj, "v_proj"));
                tensors.insert(0, hqq_tensor_exec_json(&desc.k_proj, "k_proj"));
                tensors.insert(0, hqq_tensor_exec_json(&desc.q_proj, "q_proj"));
                "split_qkv"
            };
            serde_json::json!({
                "layer_kind": "gqa",
                "backend": desc.backend,
                "format_version": desc.format_version,
                "nbits": desc.nbits,
                "metadata": {
                    "projection_mode": projection_mode,
                    "num_heads": desc.num_heads,
                    "num_kv_heads": desc.num_kv_heads,
                    "head_dim": desc.head_dim,
                    "rope_half_dim": desc.rope_half_dim,
                    "rope_cos_ptr": desc.rope_cos_ptr,
                    "rope_sin_ptr": desc.rope_sin_ptr,
                    "sm_scale": desc.sm_scale,
                    "q_norm_ptr": desc.q_norm_ptr,
                    "k_norm_ptr": desc.k_norm_ptr,
                    "gated": desc.gated,
                    "gated_q_rows": desc.gated_q_rows,
                    "gated_gate_rows": desc.gated_gate_rows,
                    "fused_q_rows": desc.fused_q_rows,
                    "fused_k_rows": desc.fused_k_rows,
                    "fused_v_rows": desc.fused_v_rows,
                    "gated_gate_uses_la_qkvz": desc.gated_gate_uses_la_qkvz,
                    "gated_uses_bf16_o_proj": desc.gated_uses_bf16_o_proj,
                    "gated_bf16_o_proj_wid": desc.gated_bf16_o_proj_wid,
                },
                "tensors": tensors,
            })
        }
        HqqExecutionDescriptor::Mla(desc) => {
            let mut tensors = vec![
                hqq_tensor_exec_json(&desc.kv_a_proj_with_mqa, "kv_a_proj_with_mqa"),
                hqq_tensor_exec_json(&desc.o_proj, "o_proj"),
            ];
            if let Some(q_a_proj) = &desc.q_a_proj {
                tensors.push(hqq_tensor_exec_json(q_a_proj, "q_a_proj"));
            }
            if let Some(q_b_proj) = &desc.q_b_proj {
                tensors.push(hqq_tensor_exec_json(q_b_proj, "q_b_proj"));
            }
            if let Some(q_proj) = &desc.q_proj {
                tensors.push(hqq_tensor_exec_json(q_proj, "q_proj"));
            }
            serde_json::json!({
                "layer_kind": "mla",
                "backend": desc.backend,
                "format_version": desc.format_version,
                "nbits": desc.nbits,
                "metadata": {
                    "num_heads": desc.num_heads,
                    "kv_lora_rank": desc.kv_lora_rank,
                    "ckv_cache_dim": desc.ckv_cache_dim,
                    "qk_nope_dim": desc.qk_nope_dim,
                    "qk_rope_dim": desc.qk_rope_dim,
                    "v_head_dim": desc.v_head_dim,
                    "q_lora_rank": desc.q_lora_rank,
                    "sm_scale": desc.sm_scale,
                    "rope_interleave": desc.rope_interleave,
                    "kv_a_norm_ptr": desc.kv_a_norm_ptr,
                    "w_kc_ptr": desc.w_kc_ptr,
                    "w_vc_ptr": desc.w_vc_ptr,
                    "ckv_cache_ptr": desc.ckv_cache_ptr,
                    "kpe_cache_ptr": desc.kpe_cache_ptr,
                    "q_a_norm_ptr": desc.q_a_norm_ptr,
                },
                "tensors": tensors,
            })
        }
        HqqExecutionDescriptor::LinearAttention(desc) => serde_json::json!({
            "layer_kind": "linear_attention",
            "backend": desc.backend,
            "format_version": desc.format_version,
            "nbits": desc.nbits,
            "metadata": {
                "num_k_heads": desc.num_k_heads,
                "num_v_heads": desc.num_v_heads,
                "k_head_dim": desc.k_head_dim,
                "v_head_dim": desc.v_head_dim,
                "head_ratio": desc.head_ratio,
                "kernel_dim": desc.kernel_dim,
                "conv_dim": desc.conv_dim,
                "scale": desc.scale,
                "conv_weight_ptr": desc.conv_weight_ptr,
                "a_log_ptr": desc.a_log_ptr,
                "dt_bias_ptr": desc.dt_bias_ptr,
                "norm_weight_ptr": desc.norm_weight_ptr,
                "conv_state_ptr": desc.conv_state_ptr,
                "recur_state_ptr": desc.recur_state_ptr,
            },
            "tensors": [
                hqq_tensor_exec_json(&desc.in_proj_qkvz, "in_proj_qkvz"),
                hqq_tensor_exec_json(&desc.in_proj_ba, "in_proj_ba"),
                hqq_tensor_exec_json(&desc.out_proj, "out_proj"),
            ],
        }),
    }
}

fn hqq_decode_dispatch_error(
    layer_idx: usize,
    expected_kind: &str,
    exec: &HqqExecutionDescriptor,
    requested_projection_mode: Option<&str>,
) -> String {
    match exec {
        HqqExecutionDescriptor::Gqa(desc) => {
            let projection_mode = requested_projection_mode.unwrap_or_else(|| {
                if desc.fused_qkv.is_some() {
                    "fused_qkv"
                } else {
                    "split_qkv"
                }
            });
            if projection_mode == "fused_qkv" {
                let fused_qkv = desc.fused_qkv.as_ref();
                format!(
                    "HQQ decode {} execution is not enabled for the current fused GQA path at layer {} (slot-backed decode runtime prepared; backend={} nbits={} format_v{} fused_qkv_present={} fused_qkv_kind={} fused_qkv_kernel_ready={} fused_qkv_rows={} fused_qkv_cols={} fused_q_rows={} fused_k_rows={} fused_v_rows={} o_proj_kind={} o_proj_kernel_ready={} gated={} gated_q_rows={} gated_gate_rows={} gated_gate_uses_la_qkvz={} gated_uses_bf16_o_proj={} gated_bf16_o_proj_wid={})",
                    expected_kind,
                    layer_idx,
                    desc.backend,
                    desc.nbits,
                    desc.format_version,
                    fused_qkv.is_some(),
                    fused_qkv.map(|tensor| tensor.runtime_kind.as_str()).unwrap_or("missing"),
                    fused_qkv.map(|tensor| tensor.kernel_ready).unwrap_or(false),
                    fused_qkv.map(|tensor| tensor.rows).unwrap_or(0),
                    fused_qkv.map(|tensor| tensor.cols).unwrap_or(0),
                    desc.fused_q_rows,
                    desc.fused_k_rows,
                    desc.fused_v_rows,
                    desc.o_proj.runtime_kind,
                    desc.o_proj.kernel_ready,
                    desc.gated,
                    desc.gated_q_rows,
                    desc.gated_gate_rows,
                    desc.gated_gate_uses_la_qkvz,
                    desc.gated_uses_bf16_o_proj,
                    desc.gated_bf16_o_proj_wid
                )
            } else {
                format!(
                    "HQQ decode {} execution is not enabled for the current split GQA path at layer {} (slot-backed decode runtime prepared; backend={} nbits={} format_v{} q_proj_kind={} q_proj_kernel_ready={} o_proj_kind={} o_proj_kernel_ready={} gated={} q_proj_rows={} q_proj_cols={} gated_q_rows={} gated_gate_rows={} gated_gate_uses_la_qkvz={} gated_uses_bf16_o_proj={} gated_bf16_o_proj_wid={})",
                    expected_kind, layer_idx, desc.backend, desc.nbits, desc.format_version, desc.q_proj.runtime_kind, desc.q_proj.kernel_ready, desc.o_proj.runtime_kind, desc.o_proj.kernel_ready, desc.gated, desc.q_proj.rows, desc.q_proj.cols, desc.gated_q_rows, desc.gated_gate_rows, desc.gated_gate_uses_la_qkvz, desc.gated_uses_bf16_o_proj, desc.gated_bf16_o_proj_wid
                )
            }
        }
        HqqExecutionDescriptor::Mla(desc) => format!(
            "HQQ decode {} execution is not ready for the current MLA path at layer {} (slot-backed HQQ runtime prepared; registered kind=mla backend={} nbits={} format_v{} q_lora_rank={} q_a_ready={} q_b_ready={} q_ready={} kv_a_ready={} o_ready={} kv_a_proj_rows={} kv_a_proj_cols={})",
            expected_kind,
            layer_idx,
            desc.backend,
            desc.nbits,
            desc.format_version,
            desc.q_lora_rank,
            desc.q_a_proj.as_ref().map_or(false, |tensor| tensor.kernel_ready),
            desc.q_b_proj.as_ref().map_or(false, |tensor| tensor.kernel_ready),
            desc.q_proj.as_ref().map_or(false, |tensor| tensor.kernel_ready),
            desc.kv_a_proj_with_mqa.kernel_ready,
            desc.o_proj.kernel_ready,
            desc.kv_a_proj_with_mqa.rows,
            desc.kv_a_proj_with_mqa.cols
        ),
        HqqExecutionDescriptor::LinearAttention(desc) => format!(
            "HQQ decode {} execution is not enabled yet at layer {} (slot-backed HQQ runtime prepared; registered kind=linear_attention backend={} nbits={} format_v{} in_proj_qkvz_rows={} in_proj_qkvz_cols={})",
            expected_kind, layer_idx, desc.backend, desc.nbits, desc.format_version, desc.in_proj_qkvz.rows, desc.in_proj_qkvz.cols
        ),
    }
}

fn hqq_gqa_split_decode_ready(
    desc: &HqqGqaExecutionDescriptor,
    gated: bool,
    num_heads: usize,
    head_dim: usize,
) -> bool {
    desc.q_proj.kernel_ready
        && desc.k_proj.kernel_ready
        && desc.v_proj.kernel_ready
        && desc.o_proj.kernel_ready
        && ((!gated && !desc.gated)
            || (gated
                && desc.gated
                && desc.q_proj.gated_split_interleaved
                && desc.q_proj.logical_rows == num_heads * head_dim
                && desc.gated_q_rows == num_heads * head_dim
                && desc.gated_gate_rows == num_heads * head_dim
                && desc.gated_gate_uses_la_qkvz
                && !desc.gated_uses_bf16_o_proj))
}

fn hqq_gqa_fused_decode_ready(
    desc: &HqqGqaExecutionDescriptor,
    gated: bool,
    num_heads: usize,
    num_kv_heads: usize,
    head_dim: usize,
) -> bool {
    let Some(fused_qkv) = desc.fused_qkv.as_ref() else {
        return false;
    };
    let q_rows = num_heads
        .checked_mul(head_dim)
        .and_then(|value| value.checked_mul(if gated { 2 } else { 1 }));
    let kv_rows = num_kv_heads.checked_mul(head_dim);
    matches!(
        (q_rows, kv_rows),
        (Some(expected_q_rows), Some(expected_kv_rows))
            if desc.gated == gated
                && fused_qkv.kernel_ready
                && desc.o_proj.kernel_ready
                && !desc.gated_uses_bf16_o_proj
                && !fused_qkv.gated_split_interleaved
                && fused_qkv.logical_rows == fused_qkv.rows
                && desc.fused_q_rows == expected_q_rows
                && desc.fused_k_rows == expected_kv_rows
                && desc.fused_v_rows == expected_kv_rows
                && fused_qkv.rows
                    == expected_q_rows
                        .checked_add(expected_kv_rows)
                        .and_then(|value| value.checked_add(expected_kv_rows))
                        .unwrap_or(usize::MAX)
                && ((!gated && desc.gated_q_rows == 0 && desc.gated_gate_rows == 0)
                    || (gated
                        && desc.gated_q_rows == num_heads * head_dim
                        && desc.gated_gate_rows == num_heads * head_dim
                        && desc.gated_gate_uses_la_qkvz))
    )
}

fn hqq_linear_attention_decode_ready(desc: &HqqLinearAttentionExecutionDescriptor) -> bool {
    desc.in_proj_qkvz.kernel_ready && desc.in_proj_ba.kernel_ready && desc.out_proj.kernel_ready
}

fn hqq_mla_decode_ready(
    desc: &HqqMlaExecutionDescriptor,
    hidden_size: usize,
    num_heads: usize,
    kv_lora_rank: usize,
    qk_nope_dim: usize,
    qk_rope_dim: usize,
    v_head_dim: usize,
    q_lora_rank: usize,
) -> bool {
    let Some(q_head_dim) = qk_nope_dim.checked_add(qk_rope_dim) else {
        return false;
    };
    let Some(q_rows) = num_heads.checked_mul(q_head_dim) else {
        return false;
    };
    let Some(o_cols) = num_heads.checked_mul(v_head_dim) else {
        return false;
    };
    let Some(kv_rows) = kv_lora_rank.checked_add(qk_rope_dim) else {
        return false;
    };
    let query_ready = if q_lora_rank > 0 {
        matches!(
            (desc.q_a_proj.as_ref(), desc.q_b_proj.as_ref()),
            (Some(q_a), Some(q_b))
                if q_a.kernel_ready
                    && q_b.kernel_ready
                    && q_a.rows == q_lora_rank
                    && q_a.cols == hidden_size
                    && q_b.rows == q_rows
                    && q_b.cols == q_lora_rank
        )
    } else {
        matches!(
            desc.q_proj.as_ref(),
            Some(q)
                if q.kernel_ready
                    && q.rows == q_rows
                    && q.cols == hidden_size
        )
    };
    query_ready
        && desc.kv_a_proj_with_mqa.kernel_ready
        && desc.kv_a_proj_with_mqa.rows == kv_rows
        && desc.kv_a_proj_with_mqa.cols == hidden_size
        && desc.o_proj.kernel_ready
        && desc.o_proj.rows == hidden_size
        && desc.o_proj.cols == o_cols
        && desc.num_heads == num_heads
        && desc.kv_lora_rank == kv_lora_rank
        && desc.qk_nope_dim == qk_nope_dim
        && desc.qk_rope_dim == qk_rope_dim
        && desc.v_head_dim == v_head_dim
        && desc.q_lora_rank == q_lora_rank
}

fn validate_hqq4_tensor_desc(
    tensor_name: &str,
    desc: &HqqTensorExecDescriptor,
) -> Result<(), String> {
    validate_hqq4_tensor_desc_for_layout(
        tensor_name,
        desc,
        "row_major_axis1_grouped_uint4_packed",
        false,
    )
}

fn hqq_expected_layout(nbits: u8, stage: &str) -> Result<&'static str, String> {
    match (nbits, stage) {
        (4, "prefill") => Ok("row_major_axis1_grouped_uint4_packed"),
        (4, "decode") => Ok("row_aligned_grouped_uint4_decode_v1"),
        (6, "prefill") => Ok("row_major_axis1_grouped_uint6_packed"),
        (6, "decode") => Ok("row_aligned_grouped_uint6_decode_v1"),
        (8, "prefill") => Ok("row_major_axis1_grouped_uint8"),
        (8, "decode") => Ok("row_aligned_grouped_uint8_decode_v1"),
        _ => Err(format!("Unsupported HQQ nbits={} stage={}", nbits, stage)),
    }
}

fn validate_hqq4_tensor_desc_for_layout(
    tensor_name: &str,
    desc: &HqqTensorExecDescriptor,
    expected_layout: &str,
    require_kernel_ready: bool,
) -> Result<(), String> {
    if desc.axis != 1 {
        return Err(format!(
            "HQQ tensor {} uses unsupported axis {} (expected axis=1)",
            tensor_name, desc.axis
        ));
    }
    if desc.layout != expected_layout {
        return Err(format!(
            "HQQ tensor {} uses unsupported layout {} (expected {})",
            tensor_name, desc.layout, expected_layout
        ));
    }
    if desc.packed_dtype != "uint8" {
        return Err(format!(
            "HQQ tensor {} uses unsupported packed dtype {}",
            tensor_name, desc.packed_dtype
        ));
    }
    if desc.scales_dtype != "float32" || desc.zeros_dtype != "float32" {
        return Err(format!(
            "HQQ tensor {} uses unsupported scale/zero dtypes {}/{}",
            tensor_name, desc.scales_dtype, desc.zeros_dtype
        ));
    }
    if desc.group_size == 0 {
        return Err(format!(
            "HQQ tensor {} has invalid group_size=0",
            tensor_name
        ));
    }
    if require_kernel_ready && !desc.kernel_ready {
        return Err(format!(
            "HQQ tensor {} decode runtime is not kernel-ready (stage={} kind={})",
            tensor_name, desc.runtime_stage, desc.runtime_kind
        ));
    }
    Ok(())
}

fn validate_hqq_tensor_desc_for_layout(
    tensor_name: &str,
    desc: &HqqTensorExecDescriptor,
    nbits: u8,
    expected_layout: &str,
    require_kernel_ready: bool,
) -> Result<(), String> {
    if desc.axis != 1 {
        return Err(format!(
            "HQQ tensor {} uses unsupported axis {} (expected axis=1)",
            tensor_name, desc.axis
        ));
    }
    if desc.layout != expected_layout {
        return Err(format!(
            "HQQ{} tensor {} uses unsupported layout {} (expected {})",
            nbits, tensor_name, desc.layout, expected_layout
        ));
    }
    if desc.packed_dtype != "uint8" {
        return Err(format!(
            "HQQ{} tensor {} uses unsupported packed dtype {}",
            nbits, tensor_name, desc.packed_dtype
        ));
    }
    if desc.scales_dtype != "float32" || desc.zeros_dtype != "float32" {
        return Err(format!(
            "HQQ{} tensor {} uses unsupported scale/zero dtypes {}/{}",
            nbits, tensor_name, desc.scales_dtype, desc.zeros_dtype
        ));
    }
    if desc.group_size == 0 {
        return Err(format!(
            "HQQ{} tensor {} has invalid group_size=0",
            nbits, tensor_name
        ));
    }
    if require_kernel_ready && !desc.kernel_ready {
        return Err(format!(
            "HQQ{} tensor {} is not kernel_ready",
            nbits, tensor_name
        ));
    }
    Ok(())
}

fn hqq_nbits_from_desc(desc: &HqqTensorExecDescriptor) -> Result<u8, String> {
    if desc.layout.contains("uint4") {
        Ok(4)
    } else if desc.layout.contains("uint6") {
        Ok(6)
    } else if desc.layout.contains("uint8") || desc.layout.contains("int8") {
        Ok(8)
    } else {
        Err(format!(
            "Cannot infer HQQ nbits from layout {}",
            desc.layout
        ))
    }
}

#[allow(clippy::too_many_arguments)]
fn build_hqq_tensors(
    layer_idx: usize,
    tensor_names: Vec<String>,
    packed_ptrs: Vec<usize>,
    scales_ptrs: Vec<usize>,
    zeros_ptrs: Vec<usize>,
    orig_rows: Vec<usize>,
    orig_cols: Vec<usize>,
    group_sizes: Vec<usize>,
    axes: Vec<usize>,
    layouts: Vec<String>,
    packed_dtypes: Vec<String>,
    scales_dtypes: Vec<String>,
    zeros_dtypes: Vec<String>,
    original_dtypes: Vec<String>,
    tensor_bytes: Vec<usize>,
) -> PyResult<HashMap<String, HqqTensorRegistration>> {
    let tensor_count = tensor_names.len();
    let lengths = [
        packed_ptrs.len(),
        scales_ptrs.len(),
        zeros_ptrs.len(),
        orig_rows.len(),
        orig_cols.len(),
        group_sizes.len(),
        axes.len(),
        layouts.len(),
        packed_dtypes.len(),
        scales_dtypes.len(),
        zeros_dtypes.len(),
        original_dtypes.len(),
        tensor_bytes.len(),
    ];
    if lengths.iter().any(|&len| len != tensor_count) {
        return Err(pyo3::exceptions::PyValueError::new_err(format!(
            "HQQ layer {} tensor descriptor field length mismatch",
            layer_idx
        )));
    }
    if tensor_count == 0 {
        return Err(pyo3::exceptions::PyValueError::new_err(format!(
            "HQQ layer {} has no tensor descriptors",
            layer_idx
        )));
    }

    let mut tensors = HashMap::new();
    for idx in 0..tensor_count {
        let tensor_name = tensor_names[idx].clone();
        if tensor_name.trim().is_empty() {
            return Err(pyo3::exceptions::PyValueError::new_err(format!(
                "HQQ layer {} has an empty tensor name",
                layer_idx
            )));
        }
        if packed_ptrs[idx] == 0 || scales_ptrs[idx] == 0 || zeros_ptrs[idx] == 0 {
            return Err(pyo3::exceptions::PyValueError::new_err(format!(
                "HQQ layer {} tensor '{}' has null pointer(s)",
                layer_idx, tensor_name
            )));
        }
        if orig_rows[idx] == 0 || orig_cols[idx] == 0 || group_sizes[idx] == 0 {
            return Err(pyo3::exceptions::PyValueError::new_err(format!(
                "HQQ layer {} tensor '{}' has invalid shape/group metadata ({}, {}, gs={})",
                layer_idx, tensor_name, orig_rows[idx], orig_cols[idx], group_sizes[idx]
            )));
        }
        if layouts[idx].trim().is_empty() {
            return Err(pyo3::exceptions::PyValueError::new_err(format!(
                "HQQ layer {} tensor '{}' has empty layout tag",
                layer_idx, tensor_name
            )));
        }
        if tensors.contains_key(&tensor_name) {
            return Err(pyo3::exceptions::PyValueError::new_err(format!(
                "Duplicate HQQ tensor '{}' for layer {}",
                tensor_name, layer_idx
            )));
        }
        tensors.insert(
            tensor_name,
            HqqTensorRegistration {
                packed_ptr: packed_ptrs[idx] as u64,
                scales_ptr: scales_ptrs[idx] as u64,
                zeros_ptr: zeros_ptrs[idx] as u64,
                rows: orig_rows[idx],
                cols: orig_cols[idx],
                group_size: group_sizes[idx],
                axis: axes[idx],
                layout: layouts[idx].clone(),
                packed_dtype: packed_dtypes[idx].clone(),
                scales_dtype: scales_dtypes[idx].clone(),
                zeros_dtype: zeros_dtypes[idx].clone(),
                original_dtype: original_dtypes[idx].clone(),
                tensor_bytes: tensor_bytes[idx],
                runtime_stage: "canonical".to_string(),
                runtime_kind: "canonical".to_string(),
                packed_row_stride_bytes: orig_cols[idx].div_ceil(2),
                scales_row_stride_bytes: orig_cols[idx].div_ceil(group_sizes[idx])
                    * std::mem::size_of::<f32>(),
                zeros_row_stride_bytes: orig_cols[idx].div_ceil(group_sizes[idx])
                    * std::mem::size_of::<f32>(),
                rows_per_tile: 1,
                row_blocks: orig_rows[idx],
                kernel_ready: false,
            },
        );
    }

    Ok(tensors)
}

fn derive_hqq_gqa_tensor_exec(
    tensor_name: &str,
    tensor: &HqqTensorExecDescriptor,
    gated: bool,
    num_heads: usize,
    head_dim: usize,
) -> PyResult<HqqTensorExecDescriptor> {
    let mut desc = tensor.clone();
    desc.logical_rows = desc.rows;
    desc.gated_split_interleaved = false;
    if gated && tensor_name == "q_proj" {
        let expected_rows = num_heads
            .checked_mul(head_dim)
            .and_then(|value| value.checked_mul(2))
            .ok_or_else(|| {
                pyo3::exceptions::PyValueError::new_err(format!(
                    "HQQ gated q_proj row count overflow for heads={} head_dim={}",
                    num_heads, head_dim
                ))
            })?;
        if desc.rows != expected_rows {
            return Err(pyo3::exceptions::PyValueError::new_err(format!(
                "HQQ gated q_proj rows mismatch: got {} expected {} (heads={} head_dim={})",
                desc.rows, expected_rows, num_heads, head_dim
            )));
        }
        desc.logical_rows = num_heads * head_dim;
        desc.gated_split_interleaved = true;
    }
    Ok(desc)
}

fn derive_hqq_gqa_fused_qkv_exec(
    tensor: &HqqTensorExecDescriptor,
    gated: bool,
    num_heads: usize,
    num_kv_heads: usize,
    head_dim: usize,
) -> PyResult<(HqqTensorExecDescriptor, usize, usize, usize)> {
    let q_rows = num_heads
        .checked_mul(head_dim)
        .and_then(|value| value.checked_mul(if gated { 2 } else { 1 }))
        .ok_or_else(|| {
            pyo3::exceptions::PyValueError::new_err(format!(
                "HQQ fused_qkv q rows overflow for heads={} kv_heads={} head_dim={} gated={}",
                num_heads, num_kv_heads, head_dim, gated
            ))
        })?;
    let k_rows = num_kv_heads.checked_mul(head_dim).ok_or_else(|| {
        pyo3::exceptions::PyValueError::new_err(format!(
            "HQQ fused_qkv k/v rows overflow for heads={} kv_heads={} head_dim={}",
            num_heads, num_kv_heads, head_dim
        ))
    })?;
    let expected_rows = q_rows
        .checked_add(k_rows)
        .and_then(|value| value.checked_add(k_rows))
        .ok_or_else(|| {
            pyo3::exceptions::PyValueError::new_err(format!(
                "HQQ fused_qkv total rows overflow for heads={} kv_heads={} head_dim={} gated={}",
                num_heads, num_kv_heads, head_dim, gated
            ))
        })?;
    if tensor.rows != expected_rows {
        return Err(pyo3::exceptions::PyValueError::new_err(format!(
            "HQQ fused_qkv rows mismatch: got {} expected {} (q_rows={} k_rows={} v_rows={} heads={} kv_heads={} head_dim={} gated={})",
            tensor.rows, expected_rows, q_rows, k_rows, k_rows, num_heads, num_kv_heads, head_dim, gated
        )));
    }

    let mut desc = tensor.clone();
    desc.logical_rows = desc.rows;
    desc.gated_split_interleaved = false;
    Ok((desc, q_rows, k_rows, k_rows))
}

fn attach_hqq_decode_sidecars(
    exec: &mut HqqExecutionDescriptor,
    sidecars: &[HqqPrefillSidecarRegistration],
) {
    let for_tensor = |tensor_name: &str| -> Vec<HqqPrefillSidecarRegistration> {
        sidecars
            .iter()
            .filter(|sidecar| {
                sidecar.mode == "int8_exception" && sidecar.tensor_name == tensor_name
            })
            .cloned()
            .collect()
    };
    match exec {
        HqqExecutionDescriptor::Gqa(desc) => {
            desc.q_proj.decode_sidecars = for_tensor("q_proj");
            desc.k_proj.decode_sidecars = for_tensor("k_proj");
            desc.v_proj.decode_sidecars = for_tensor("v_proj");
            if let Some(fused_qkv) = desc.fused_qkv.as_mut() {
                fused_qkv.decode_sidecars = for_tensor("fused_qkv");
            }
            desc.o_proj.decode_sidecars = for_tensor("o_proj");
        }
        HqqExecutionDescriptor::Mla(desc) => {
            if let Some(q_a_proj) = desc.q_a_proj.as_mut() {
                q_a_proj.decode_sidecars = for_tensor("q_a_proj");
            }
            if let Some(q_b_proj) = desc.q_b_proj.as_mut() {
                q_b_proj.decode_sidecars = for_tensor("q_b_proj");
            }
            if let Some(q_proj) = desc.q_proj.as_mut() {
                q_proj.decode_sidecars = for_tensor("q_proj");
            }
            desc.kv_a_proj_with_mqa.decode_sidecars = for_tensor("kv_a_proj_with_mqa");
            desc.o_proj.decode_sidecars = for_tensor("o_proj");
        }
        HqqExecutionDescriptor::LinearAttention(desc) => {
            desc.in_proj_qkvz.decode_sidecars = for_tensor("in_proj_qkvz");
            desc.in_proj_ba.decode_sidecars = for_tensor("in_proj_ba");
            desc.out_proj.decode_sidecars = for_tensor("out_proj");
        }
    }
}

fn register_hqq_attention_layer_common(
    graph: &mut GpuDecodeGraph,
    layer_idx: usize,
    layer_kind: &str,
    input_norm_ptr: usize,
    input_norm_size: usize,
    post_attn_norm_ptr: usize,
    post_attn_norm_size: usize,
    backend: &str,
    nbits: usize,
    format_version: usize,
    metadata: HqqLayerMetadata,
    tensors: HashMap<String, HqqTensorRegistration>,
) -> PyResult<()> {
    if nbits != 4 && nbits != 6 && nbits != 8 {
        return Err(pyo3::exceptions::PyValueError::new_err(format!(
            "Native HQQ registration only accepts nbits=4, nbits=6, or nbits=8 today, got {}",
            nbits
        )));
    }
    match layer_kind {
        "linear_attention" | "gqa" | "mla" => {}
        _ => {
            return Err(pyo3::exceptions::PyValueError::new_err(format!(
                "Unsupported HQQ layer kind '{}'",
                layer_kind
            )))
        }
    }
    if backend.trim().is_empty() {
        return Err(pyo3::exceptions::PyValueError::new_err(
            "HQQ backend tag must not be empty",
        ));
    }

    while graph.layers.len() <= layer_idx {
        graph.layers.push(GpuDecodeLayer::placeholder());
    }
    let existing_gqa_o_proj_wid = match &graph.layers[layer_idx].attn {
        GpuAttnConfig::GQA { o_proj, .. } if *o_proj != 0 => Some(*o_proj),
        _ => None,
    };

    let mut hqq_exec = match &metadata {
        HqqLayerMetadata::Gqa {
            num_heads,
            num_kv_heads,
            head_dim,
            rope_half_dim,
            rope_cos_ptr: metadata_rope_cos_ptr,
            rope_sin_ptr: metadata_rope_sin_ptr,
            sm_scale,
            q_norm_ptr,
            k_norm_ptr,
            gated,
            head_gate_proj: _head_gate_proj,
        } => {
            let q_proj = required_hqq_tensor_exec(&tensors, layer_idx, layer_kind, "q_proj")?;
            let k_proj = required_hqq_tensor_exec(&tensors, layer_idx, layer_kind, "k_proj")?;
            let v_proj = required_hqq_tensor_exec(&tensors, layer_idx, layer_kind, "v_proj")?;
            let o_proj = required_hqq_tensor_exec(&tensors, layer_idx, layer_kind, "o_proj")?;
            let fused_qkv = optional_hqq_tensor_exec(&tensors, "fused_qkv");
            let q_proj =
                derive_hqq_gqa_tensor_exec("q_proj", &q_proj, *gated, *num_heads, *head_dim)?;
            let k_proj =
                derive_hqq_gqa_tensor_exec("k_proj", &k_proj, *gated, *num_heads, *head_dim)?;
            let v_proj =
                derive_hqq_gqa_tensor_exec("v_proj", &v_proj, *gated, *num_heads, *head_dim)?;
            let o_proj =
                derive_hqq_gqa_tensor_exec("o_proj", &o_proj, *gated, *num_heads, *head_dim)?;
            let (fused_qkv, fused_q_rows, fused_k_rows, fused_v_rows) =
                if let Some(fused_qkv) = fused_qkv.as_ref() {
                    let (desc, q_rows, k_rows, v_rows) = derive_hqq_gqa_fused_qkv_exec(
                        fused_qkv,
                        *gated,
                        *num_heads,
                        *num_kv_heads,
                        *head_dim,
                    )?;
                    (Some(desc), q_rows, k_rows, v_rows)
                } else {
                    (None, 0, 0, 0)
                };
            HqqExecutionDescriptor::Gqa(HqqGqaExecutionDescriptor {
                backend: backend.to_string(),
                format_version,
                nbits: nbits as u8,
                q_proj,
                k_proj,
                v_proj,
                fused_qkv,
                o_proj,
                num_heads: *num_heads,
                num_kv_heads: *num_kv_heads,
                head_dim: *head_dim,
                rope_half_dim: *rope_half_dim,
                rope_cos_ptr: *metadata_rope_cos_ptr,
                rope_sin_ptr: *metadata_rope_sin_ptr,
                sm_scale: *sm_scale,
                q_norm_ptr: *q_norm_ptr,
                k_norm_ptr: *k_norm_ptr,
                gated: *gated,
                gated_q_rows: if *gated { num_heads * head_dim } else { 0 },
                gated_gate_rows: if *gated { num_heads * head_dim } else { 0 },
                fused_q_rows,
                fused_k_rows,
                fused_v_rows,
                gated_gate_uses_la_qkvz: *gated,
                gated_uses_bf16_o_proj: false,
                gated_bf16_o_proj_wid: existing_gqa_o_proj_wid.unwrap_or(0),
            })
        }
        HqqLayerMetadata::Mla {
            num_heads,
            kv_lora_rank,
            ckv_cache_dim,
            qk_nope_dim,
            qk_rope_dim,
            v_head_dim,
            q_lora_rank,
            sm_scale,
            rope_interleave,
            kv_a_norm_ptr,
            w_kc_ptr,
            w_vc_ptr,
            ckv_cache_ptr,
            kpe_cache_ptr,
            q_a_norm_ptr,
        } => HqqExecutionDescriptor::Mla(HqqMlaExecutionDescriptor {
            backend: backend.to_string(),
            format_version,
            nbits: nbits as u8,
            q_a_proj: optional_hqq_tensor_exec(&tensors, "q_a_proj"),
            q_b_proj: optional_hqq_tensor_exec(&tensors, "q_b_proj"),
            q_proj: optional_hqq_tensor_exec(&tensors, "q_proj"),
            kv_a_proj_with_mqa: required_hqq_tensor_exec(
                &tensors,
                layer_idx,
                layer_kind,
                "kv_a_proj_with_mqa",
            )?,
            o_proj: required_hqq_tensor_exec(&tensors, layer_idx, layer_kind, "o_proj")?,
            num_heads: *num_heads,
            kv_lora_rank: *kv_lora_rank,
            ckv_cache_dim: *ckv_cache_dim,
            qk_nope_dim: *qk_nope_dim,
            qk_rope_dim: *qk_rope_dim,
            v_head_dim: *v_head_dim,
            q_lora_rank: *q_lora_rank,
            sm_scale: *sm_scale,
            rope_interleave: *rope_interleave,
            kv_a_norm_ptr: *kv_a_norm_ptr,
            w_kc_ptr: *w_kc_ptr,
            w_vc_ptr: *w_vc_ptr,
            ckv_cache_ptr: *ckv_cache_ptr,
            kpe_cache_ptr: *kpe_cache_ptr,
            q_a_norm_ptr: *q_a_norm_ptr,
        }),
        HqqLayerMetadata::LinearAttention {
            num_k_heads,
            num_v_heads,
            k_head_dim,
            v_head_dim,
            head_ratio,
            kernel_dim,
            conv_dim,
            scale,
            conv_weight_ptr,
            a_log_ptr,
            dt_bias_ptr,
            norm_weight_ptr,
            conv_state_ptr,
            recur_state_ptr,
        } => HqqExecutionDescriptor::LinearAttention(HqqLinearAttentionExecutionDescriptor {
            backend: backend.to_string(),
            format_version,
            nbits: nbits as u8,
            in_proj_qkvz: required_hqq_tensor_exec(
                &tensors,
                layer_idx,
                layer_kind,
                "in_proj_qkvz",
            )?,
            in_proj_ba: required_hqq_tensor_exec(&tensors, layer_idx, layer_kind, "in_proj_ba")?,
            out_proj: required_hqq_tensor_exec(&tensors, layer_idx, layer_kind, "out_proj")?,
            num_k_heads: *num_k_heads,
            num_v_heads: *num_v_heads,
            k_head_dim: *k_head_dim,
            v_head_dim: *v_head_dim,
            head_ratio: *head_ratio,
            kernel_dim: *kernel_dim,
            conv_dim: *conv_dim,
            scale: *scale,
            conv_weight_ptr: *conv_weight_ptr,
            a_log_ptr: *a_log_ptr,
            dt_bias_ptr: *dt_bias_ptr,
            norm_weight_ptr: *norm_weight_ptr,
            conv_state_ptr: *conv_state_ptr,
            recur_state_ptr: *recur_state_ptr,
        }),
    };

    let decode_sidecars = graph.layers[layer_idx].hqq_prefill_sidecars.clone();
    attach_hqq_decode_sidecars(&mut hqq_exec, &decode_sidecars);
    let decode_int8_exception_rows: usize = decode_sidecars
        .iter()
        .filter(|sidecar| sidecar.mode == "int8_exception")
        .map(|sidecar| sidecar.row_group_count)
        .sum();
    if decode_int8_exception_rows > 0 {
        let tensors: Vec<String> = decode_sidecars
            .iter()
            .filter(|sidecar| sidecar.mode == "int8_exception")
            .map(|sidecar| sidecar.tensor_name.clone())
            .collect();
        log::info!(
            "HQQ decode INT8 exception sidecars active: layer={} kind={} tensors={} row_groups={}",
            layer_idx,
            layer_kind,
            tensors.join(","),
            decode_int8_exception_rows,
        );
    }

    graph.layers[layer_idx].input_norm_ptr = input_norm_ptr as u64;
    graph.layers[layer_idx].input_norm_size = input_norm_size;
    graph.layers[layer_idx].post_attn_norm_ptr = post_attn_norm_ptr as u64;
    graph.layers[layer_idx].post_attn_norm_size = post_attn_norm_size;
    graph.layers[layer_idx].attn = match (&graph.layers[layer_idx].attn, &metadata) {
        (
            GpuAttnConfig::GQA {
                q_proj,
                k_proj,
                v_proj,
                o_proj,
                fused_qkv,
                head_gate_proj: existing_head_gate_proj,
                ..
            },
            HqqLayerMetadata::Gqa {
                num_heads,
                num_kv_heads,
                head_dim,
                rope_half_dim,
                rope_cos_ptr,
                rope_sin_ptr,
                sm_scale,
                q_norm_ptr,
                k_norm_ptr,
                gated,
                head_gate_proj: metadata_head_gate_proj,
            },
        ) => GpuAttnConfig::GQA {
            q_proj: *q_proj,
            k_proj: *k_proj,
            v_proj: *v_proj,
            o_proj: *o_proj,
            fused_qkv: *fused_qkv,
            head_gate_proj: (*metadata_head_gate_proj).or(*existing_head_gate_proj),
            num_heads: *num_heads,
            num_kv_heads: *num_kv_heads,
            head_dim: *head_dim,
            rope_half_dim: *rope_half_dim,
            rope_cos_ptr: *rope_cos_ptr,
            rope_sin_ptr: *rope_sin_ptr,
            sm_scale: *sm_scale,
            q_norm_ptr: *q_norm_ptr,
            k_norm_ptr: *k_norm_ptr,
            gated: *gated,
        },
        (
            GpuAttnConfig::MLA {
                q_a_proj,
                q_b_proj,
                q_proj,
                kv_a_proj,
                o_proj,
                ..
            },
            HqqLayerMetadata::Mla {
                num_heads,
                kv_lora_rank,
                ckv_cache_dim,
                qk_nope_dim,
                qk_rope_dim,
                v_head_dim,
                q_lora_rank,
                sm_scale,
                rope_interleave,
                kv_a_norm_ptr,
                w_kc_ptr,
                w_vc_ptr,
                ckv_cache_ptr,
                kpe_cache_ptr,
                q_a_norm_ptr,
            },
        ) => GpuAttnConfig::MLA {
            q_a_proj: *q_a_proj,
            q_b_proj: *q_b_proj,
            q_a_norm_ptr: *q_a_norm_ptr,
            q_proj: *q_proj,
            kv_a_proj: *kv_a_proj,
            kv_a_norm_ptr: *kv_a_norm_ptr,
            w_kc_ptr: *w_kc_ptr,
            w_vc_ptr: *w_vc_ptr,
            o_proj: *o_proj,
            num_heads: *num_heads,
            kv_lora_rank: *kv_lora_rank,
            ckv_cache_dim: *ckv_cache_dim,
            qk_nope_dim: *qk_nope_dim,
            qk_rope_dim: *qk_rope_dim,
            v_head_dim: *v_head_dim,
            q_lora_rank: *q_lora_rank,
            sm_scale: *sm_scale,
            rope_interleave: *rope_interleave,
            ckv_cache_ptr: *ckv_cache_ptr,
            kpe_cache_ptr: *kpe_cache_ptr,
        },
        (
            GpuAttnConfig::LinearAttention {
                in_proj_qkvz,
                in_proj_ba,
                out_proj,
                ..
            },
            HqqLayerMetadata::LinearAttention {
                num_k_heads,
                num_v_heads,
                k_head_dim,
                v_head_dim,
                head_ratio,
                kernel_dim,
                conv_dim,
                scale,
                conv_weight_ptr,
                a_log_ptr,
                dt_bias_ptr,
                norm_weight_ptr,
                conv_state_ptr,
                recur_state_ptr,
            },
        ) => GpuAttnConfig::LinearAttention {
            in_proj_qkvz: *in_proj_qkvz,
            in_proj_ba: *in_proj_ba,
            out_proj: *out_proj,
            conv_weight_ptr: *conv_weight_ptr,
            a_log_ptr: *a_log_ptr,
            dt_bias_ptr: *dt_bias_ptr,
            norm_weight_ptr: *norm_weight_ptr,
            nk: *num_k_heads,
            nv: *num_v_heads,
            dk: *k_head_dim,
            dv: *v_head_dim,
            hr: *head_ratio,
            kernel_dim: *kernel_dim,
            conv_dim: *conv_dim,
            scale: *scale,
            conv_state_ptr: *conv_state_ptr,
            recur_state_ptr: *recur_state_ptr,
        },
        (
            _,
            HqqLayerMetadata::Gqa {
                num_heads,
                num_kv_heads,
                head_dim,
                rope_half_dim,
                rope_cos_ptr: metadata_rope_cos_ptr,
                rope_sin_ptr: metadata_rope_sin_ptr,
                sm_scale,
                q_norm_ptr,
                k_norm_ptr,
                gated,
                head_gate_proj,
            },
        ) => GpuAttnConfig::GQA {
            q_proj: 0,
            k_proj: 0,
            v_proj: 0,
            o_proj: if *gated {
                existing_gqa_o_proj_wid.unwrap_or(0)
            } else {
                0
            },
            fused_qkv: None,
            head_gate_proj: *head_gate_proj,
            num_heads: *num_heads,
            num_kv_heads: *num_kv_heads,
            head_dim: *head_dim,
            rope_half_dim: *rope_half_dim,
            rope_cos_ptr: *metadata_rope_cos_ptr,
            rope_sin_ptr: *metadata_rope_sin_ptr,
            sm_scale: *sm_scale,
            q_norm_ptr: *q_norm_ptr,
            k_norm_ptr: *k_norm_ptr,
            gated: *gated,
        },
        (
            _,
            HqqLayerMetadata::Mla {
                num_heads,
                kv_lora_rank,
                ckv_cache_dim,
                qk_nope_dim,
                qk_rope_dim,
                v_head_dim,
                q_lora_rank,
                sm_scale,
                rope_interleave,
                kv_a_norm_ptr,
                w_kc_ptr,
                w_vc_ptr,
                ckv_cache_ptr,
                kpe_cache_ptr,
                q_a_norm_ptr,
            },
        ) => GpuAttnConfig::MLA {
            q_a_proj: None,
            q_b_proj: None,
            q_a_norm_ptr: *q_a_norm_ptr,
            q_proj: None,
            kv_a_proj: 0,
            kv_a_norm_ptr: *kv_a_norm_ptr,
            w_kc_ptr: *w_kc_ptr,
            w_vc_ptr: *w_vc_ptr,
            o_proj: 0,
            num_heads: *num_heads,
            kv_lora_rank: *kv_lora_rank,
            ckv_cache_dim: *ckv_cache_dim,
            qk_nope_dim: *qk_nope_dim,
            qk_rope_dim: *qk_rope_dim,
            v_head_dim: *v_head_dim,
            q_lora_rank: *q_lora_rank,
            sm_scale: *sm_scale,
            rope_interleave: *rope_interleave,
            ckv_cache_ptr: *ckv_cache_ptr,
            kpe_cache_ptr: *kpe_cache_ptr,
        },
        (
            _,
            HqqLayerMetadata::LinearAttention {
                num_k_heads,
                num_v_heads,
                k_head_dim,
                v_head_dim,
                head_ratio,
                kernel_dim,
                conv_dim,
                scale,
                conv_weight_ptr,
                a_log_ptr,
                dt_bias_ptr,
                norm_weight_ptr,
                conv_state_ptr,
                recur_state_ptr,
            },
        ) => GpuAttnConfig::LinearAttention {
            in_proj_qkvz: 0,
            in_proj_ba: 0,
            out_proj: 0,
            conv_weight_ptr: *conv_weight_ptr,
            a_log_ptr: *a_log_ptr,
            dt_bias_ptr: *dt_bias_ptr,
            norm_weight_ptr: *norm_weight_ptr,
            nk: *num_k_heads,
            nv: *num_v_heads,
            dk: *k_head_dim,
            dv: *v_head_dim,
            hr: *head_ratio,
            kernel_dim: *kernel_dim,
            conv_dim: *conv_dim,
            scale: *scale,
            conv_state_ptr: *conv_state_ptr,
            recur_state_ptr: *recur_state_ptr,
        },
    };
    graph.layers[layer_idx].hqq = Some(HqqLayerRegistration {
        backend: backend.to_string(),
        layer_kind: layer_kind.to_string(),
        format_version,
        nbits: nbits as u8,
        metadata,
        tensors,
    });
    graph.layers[layer_idx].hqq_exec = Some(hqq_exec);
    log::info!(
        "GpuDecodeStore: registered HQQ layer {} kind={} tensors={} backend={} nbits={} format_v{}",
        layer_idx,
        layer_kind,
        graph.layers[layer_idx]
            .hqq
            .as_ref()
            .map(|v| v.tensors.len())
            .unwrap_or(0),
        backend,
        nbits,
        format_version,
    );
    Ok(())
}

#[allow(dead_code)]
enum GpuAttnConfig {
    LinearAttention {
        in_proj_qkvz: usize,
        in_proj_ba: usize,
        out_proj: usize,
        // Conv + recurrence params
        conv_weight_ptr: u64, // [conv_dim, kernel_dim] FP32 on GPU
        a_log_ptr: u64,
        dt_bias_ptr: u64,
        norm_weight_ptr: u64,
        nk: usize,
        nv: usize,
        dk: usize,
        dv: usize,
        hr: usize,
        kernel_dim: usize,
        conv_dim: usize,
        scale: f32,
        conv_state_ptr: u64,  // [conv_dim, kernel_dim] FP32 on GPU
        recur_state_ptr: u64, // [nv, dk, dv] FP32 on GPU
    },
    GQA {
        q_proj: usize,
        k_proj: usize,
        v_proj: usize,
        o_proj: usize,
        fused_qkv: Option<usize>,
        head_gate_proj: Option<usize>,
        num_heads: usize,
        num_kv_heads: usize,
        head_dim: usize,
        rope_half_dim: usize,
        rope_cos_ptr: u64,
        rope_sin_ptr: u64,
        sm_scale: f32,
        q_norm_ptr: u64, // 0 if no QK norm
        k_norm_ptr: u64,
        gated: bool,
    },
    MLA {
        // Q projection: q_lora path (q_a_proj → layernorm → q_b_proj) or direct q_proj
        q_a_proj: Option<usize>, // None for direct q_proj
        q_b_proj: Option<usize>,
        q_a_norm_ptr: u64,     // FP32 layernorm weight for q_a (0 if direct)
        q_proj: Option<usize>, // Some for direct, None for q_lora
        // KV projection
        kv_a_proj: usize,
        kv_a_norm_ptr: u64, // FP32 layernorm weight for kv_a
        // Absorbed weights (BF16, kept on GPU permanently)
        w_kc_ptr: u64, // [num_heads, qk_nope_dim, ckv_cache_dim] BF16
        w_vc_ptr: u64, // [num_heads, v_head_dim, ckv_cache_dim] BF16
        // Output
        o_proj: usize,
        // Dimensions
        num_heads: usize,
        kv_lora_rank: usize, // real kv_lora_rank from model (e.g. 256 for Mistral)
        ckv_cache_dim: usize, // effective ckv dim in cache (≥512 for MLA decode)
        qk_nope_dim: usize,
        qk_rope_dim: usize,
        v_head_dim: usize,
        q_lora_rank: usize, // 0 if direct q_proj
        sm_scale: f32,
        rope_interleave: bool,
        // MLA KV cache (separate ckv and kpe signed-INT4 block stores)
        ckv_cache_ptr: u64,
        kpe_cache_ptr: u64,
    },
    /// Mamba2 selective state space layer (Nemotron-H hybrid models).
    /// O(1) per-token decode, no KV cache. State is always GPU-resident.
    Mamba2 {
        in_proj: usize, // weight ID: hidden_size -> expand * (head_dim + 2*state_size + 1) * num_heads
        out_proj: usize, // weight ID: expand * head_dim * num_heads -> hidden_size
        conv_weight_ptr: u64, // [conv_dim, conv_kernel] FP32 on GPU
        a_ptr: u64,     // [num_heads] FP32 — discretization parameter A
        d_ptr: u64,     // [num_heads] FP32 — skip connection D
        dt_bias_ptr: u64, // [num_heads] FP32
        norm_weight_ptr: u64, // [expand * head_dim * num_heads] FP32 — output RMSNorm
        num_heads: usize, // 128 for Nemotron
        head_dim: usize, // 64
        state_size: usize, // 128
        expand: usize,  // 2
        conv_kernel: usize, // 4
        conv_dim: usize, // expand * head_dim * num_heads (conv input dim)
        conv_state_ptr: u64, // [conv_dim, conv_kernel] FP32 on GPU (per-sequence)
        ssm_state_ptr: u64, // [num_heads, head_dim, state_size] FP32 on GPU (per-sequence)
    },
}

