    /// Register an MLA (Multi-head Latent Attention) layer for GPU decode.
    #[pyo3(signature = (
        layer_idx, input_norm_ptr, input_norm_size,
        post_attn_norm_ptr, post_attn_norm_size,
        kv_a_proj_wid, o_proj_wid,
        kv_a_norm_ptr, w_kc_ptr, w_vc_ptr,
        num_heads, kv_lora_rank, qk_nope_dim, qk_rope_dim, v_head_dim,
        sm_scale, rope_interleave,
        ckv_cache_ptr, kpe_cache_ptr,
        q_a_proj_wid=None, q_b_proj_wid=None, q_a_norm_ptr=0,
        q_proj_wid=None, q_lora_rank=0, ckv_cache_dim=0
    ))]
    fn register_mla_layer(
        &mut self,
        layer_idx: usize,
        input_norm_ptr: usize,
        input_norm_size: usize,
        post_attn_norm_ptr: usize,
        post_attn_norm_size: usize,
        kv_a_proj_wid: usize,
        o_proj_wid: usize,
        kv_a_norm_ptr: usize,
        w_kc_ptr: usize,
        w_vc_ptr: usize,
        num_heads: usize,
        kv_lora_rank: usize,
        qk_nope_dim: usize,
        qk_rope_dim: usize,
        v_head_dim: usize,
        sm_scale: f32,
        rope_interleave: bool,
        ckv_cache_ptr: usize,
        kpe_cache_ptr: usize,
        q_a_proj_wid: Option<usize>,
        q_b_proj_wid: Option<usize>,
        q_a_norm_ptr: usize,
        q_proj_wid: Option<usize>,
        q_lora_rank: usize,
        ckv_cache_dim: usize,
    ) -> PyResult<()> {
        // ckv_cache_dim: effective dimension in cache (≥512 for MLA decode).
        // If 0 (default), use kv_lora_rank directly.
        let ckv_cache_dim = if ckv_cache_dim == 0 {
            kv_lora_rank
        } else {
            ckv_cache_dim
        };

        let graph = self
            .graph
            .as_mut()
            .ok_or_else(|| pyo3::exceptions::PyRuntimeError::new_err("Call configure first"))?;
        while graph.layers.len() <= layer_idx {
            graph.layers.push(GpuDecodeLayer::placeholder());
        }
        graph.layers[layer_idx].input_norm_ptr = input_norm_ptr as u64;
        graph.layers[layer_idx].input_norm_size = input_norm_size;
        graph.layers[layer_idx].post_attn_norm_ptr = post_attn_norm_ptr as u64;
        graph.layers[layer_idx].post_attn_norm_size = post_attn_norm_size;
        graph.layers[layer_idx].hqq = None;
        graph.layers[layer_idx].hqq_exec = None;
        graph.layers[layer_idx].attn = GpuAttnConfig::MLA {
            q_a_proj: q_a_proj_wid,
            q_b_proj: q_b_proj_wid,
            q_a_norm_ptr: q_a_norm_ptr as u64,
            q_proj: q_proj_wid,
            kv_a_proj: kv_a_proj_wid,
            kv_a_norm_ptr: kv_a_norm_ptr as u64,
            w_kc_ptr: w_kc_ptr as u64,
            w_vc_ptr: w_vc_ptr as u64,
            o_proj: o_proj_wid,
            num_heads,
            kv_lora_rank,
            ckv_cache_dim,
            qk_nope_dim,
            qk_rope_dim,
            v_head_dim,
            q_lora_rank,
            sm_scale,
            rope_interleave,
            ckv_cache_ptr: ckv_cache_ptr as u64,
            kpe_cache_ptr: kpe_cache_ptr as u64,
        };
        log::info!("GpuDecodeStore: registered MLA layer {} (heads={}, kv_lora_rank={}, ckv_cache_dim={}, nope={}, rope={}, v_hd={})",
            layer_idx, num_heads, kv_lora_rank, ckv_cache_dim, qk_nope_dim, qk_rope_dim, v_head_dim);
        Ok(())
    }

    /// Register a Mamba2 SSM layer for GPU decode (Nemotron-H hybrid models).
    /// Mamba2 layers have O(1) per-token state, no KV cache, always GPU-resident.
    #[allow(clippy::too_many_arguments)]
    fn register_mamba2_layer(
        &mut self,
        layer_idx: usize,
        input_norm_ptr: usize,
        input_norm_size: usize,
        post_attn_norm_ptr: usize,
        post_attn_norm_size: usize,
        in_proj_wid: usize,
        out_proj_wid: usize,
        conv_weight_ptr: usize,
        a_ptr: usize,
        d_ptr: usize,
        dt_bias_ptr: usize,
        norm_weight_ptr: usize,
        conv_state_ptr: usize,
        ssm_state_ptr: usize,
        num_heads: usize,
        head_dim: usize,
        state_size: usize,
        expand: usize,
        conv_kernel: usize,
        conv_dim: usize,
    ) -> PyResult<()> {
        let graph = self
            .graph
            .as_mut()
            .ok_or_else(|| pyo3::exceptions::PyRuntimeError::new_err("Call configure first"))?;
        while graph.layers.len() <= layer_idx {
            graph.layers.push(GpuDecodeLayer::placeholder());
        }
        graph.layers[layer_idx].input_norm_ptr = input_norm_ptr as u64;
        graph.layers[layer_idx].input_norm_size = input_norm_size;
        graph.layers[layer_idx].post_attn_norm_ptr = post_attn_norm_ptr as u64;
        graph.layers[layer_idx].post_attn_norm_size = post_attn_norm_size;
        graph.layers[layer_idx].hqq = None;
        graph.layers[layer_idx].hqq_exec = None;
        graph.layers[layer_idx].attn = GpuAttnConfig::Mamba2 {
            in_proj: in_proj_wid,
            out_proj: out_proj_wid,
            conv_weight_ptr: conv_weight_ptr as u64,
            a_ptr: a_ptr as u64,
            d_ptr: d_ptr as u64,
            dt_bias_ptr: dt_bias_ptr as u64,
            norm_weight_ptr: norm_weight_ptr as u64,
            num_heads,
            head_dim,
            state_size,
            expand,
            conv_kernel,
            conv_dim,
            conv_state_ptr: conv_state_ptr as u64,
            ssm_state_ptr: ssm_state_ptr as u64,
        };
        // Allocate mamba2 conv_out buffer if not yet allocated (sized to max conv_dim)
        if graph.mamba2_conv_out_size < conv_dim {
            graph.d_mamba2_conv_out =
                Some(self.device.alloc_zeros::<f32>(conv_dim).map_err(|e| {
                    pyo3::exceptions::PyRuntimeError::new_err(format!(
                        "alloc mamba2_conv_out: {:?}",
                        e
                    ))
                })?);
            graph.mamba2_conv_out_size = conv_dim;
        }
        if let Some(in_w) = graph.weights.get(in_proj_wid) {
            if in_w.dtype == 0 {
                let cols = in_w.cols;
                let rows = in_w.rows;
                let candidate_cols = BF16_MAMBA2_IN_PROJ_PREFILL_EQUIV_MIN_COLS;
                let input_elems = cols.checked_mul(candidate_cols).ok_or_else(|| {
                    pyo3::exceptions::PyRuntimeError::new_err(format!(
                        "Mamba2 graph BF16 input size overflow cols={} candidate_cols={}",
                        cols, candidate_cols
                    ))
                })?;
                let output_elems = rows.checked_mul(candidate_cols).ok_or_else(|| {
                    pyo3::exceptions::PyRuntimeError::new_err(format!(
                        "Mamba2 graph BF16 output size overflow rows={} candidate_cols={}",
                        rows, candidate_cols
                    ))
                })?;
                if graph.mamba2_bf16_graph_input_size < input_elems {
                    graph.d_mamba2_bf16_graph_input =
                        Some(self.device.alloc_zeros::<u16>(input_elems).map_err(|e| {
                            pyo3::exceptions::PyRuntimeError::new_err(format!(
                                "alloc mamba2_bf16_graph_input: {:?}",
                                e
                            ))
                        })?);
                    graph.mamba2_bf16_graph_input_size = input_elems;
                }
                if graph.mamba2_bf16_graph_output_size < output_elems {
                    graph.d_mamba2_bf16_graph_output =
                        Some(self.device.alloc_zeros::<u16>(output_elems).map_err(|e| {
                            pyo3::exceptions::PyRuntimeError::new_err(format!(
                                "alloc mamba2_bf16_graph_output: {:?}",
                                e
                            ))
                        })?);
                    graph.mamba2_bf16_graph_output_size = output_elems;
                }
            }
        }
        log::info!("GpuDecodeStore: registered Mamba2 layer {} (heads={}, hd={}, state={}, conv_dim={}), total_layers={}",
            layer_idx, num_heads, head_dim, state_size, conv_dim, graph.layers.len());
        Ok(())
    }

